<?php
namespace App\Service\HelloAsso;
final readonly class HelloAssoWebhookPayload{public function __construct(public string $eventType,public string $paymentId,public ?string $paymentState,public ?string $orderId,public ?string $organizationSlug,public ?string $formType,public ?string $formSlug,public ?string $tierId,public ?int $amount,public ?int $tierAmount,public ?string $receiptUrl,public ?string $payerEmail,public ?string $payerFirstname,public ?string $payerLastname,public array $metadata,public array $customFieldValues,public string $payloadHash){}public function isExpected(string $org,string $type,string $slug):bool{return strcasecmp($this->eventType,'Payment')===0&&$this->organizationSlug===$org&&strcasecmp((string)$this->formType,$type)===0&&$this->formSlug===$slug;}}
